WF.el("div",{className:"wf-markdown",markdown:"These rules hold for every command unless its entry says otherwise:\n\n- **The project directory.** A command that works on a project uses the current directory. `-d DIR` (or `--dir DIR`) names another one; a command that takes a `PATH` argument instead takes the directory, or sometimes one file, as that argument.\n- **Exit status.** A command exits `0` when it succeeds and non-zero when it fails, so each command works as a CI step without a wrapper. A build that stops on its findings exits `1`; a build that cannot run at all — a file it cannot read, a config it cannot load — exits `2`.\n- **`--json`.** A describing command prints a human-readable report by default and, with `--json`, the same information as JSON for a tool.\n- **Previews.** Every command that writes files has a flag that shows what it would do and writes nothing: `wf fmt --check`, `wf migrate --check`, `wf fix --dry-run`. `wf commands` names that flag for each command."});_e6480.appendChild(_e6602);const _e6603=WF.el("h2",{className:"wf-heading",id:"scaffolding-and-building"},"Scaffolding and building");_e6480.appendChild(_e6603);const _e6604=WF.el("h3",{className:"wf-heading",id:"wf-init"},"wf init");_e6480.appendChild(_e6604);const _e6605=WF.el("div",{className:"wf-markdown",markdown:"Creates a new project directory with a config, a `.gitignore`, an `AGENTS.md` and a small working application.\n\n**Usage:** `wf init [OPTIONS] NAME`"});_e6480.appendChild(_e6605);const _e6606=WF.el("table",{className:"wf-table"},WF.el("caption",{className:"wf-visually-hidden"},"wf init"));const _e6607=WF.el("thead",{});const _e6608=WF.el("tr",{});const _e6609=WF.el("th",{scope:"col"},"Option");_e6608.appendChild(_e6609);const _e6610=WF.el("th",{scope:"col"},"Value");_e6608.appendChild(_e6610);const _e6611=WF.el("th",{scope:"col"},"Default");_e6608.appendChild(_e6611);const _e6612=WF.el("th",{scope:"col"},"Meaning");_e6608.appendChild(_e6612);_e6607.appendChild(_e6608);